package wgmodern;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.GraphicsStatus;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;import net.minecraft.nbt.CompoundTag;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.event.TickEvent;import net.minecraftforge.client.event.RenderLevelStageEvent;import com.mojang.blaze3d.vertex.*;
/** FXBeamPower parity: two perpendicular beam1 ribbons, pulsing opacity and animated endpoint flare. */
@Mod.EventBusSubscriber(modid="witchinggadgets",value=Dist.CLIENT)
public class GuidingThreadRenderer {
 private static final ResourceLocation BEAM=new ResourceLocation("thaumcraft","textures/misc/beam1.png"),ATLAS=new ResourceLocation("thaumcraft","textures/misc/particles.png");
 private static final Map<String,Beam> LINES=new LinkedHashMap<>();private static net.minecraft.client.multiplayer.ClientLevel current;
 private static class Beam {Vec3 from,to,oldFrom,oldTo;int age,left=8,color=0x808080;float opacity=.3f;Beam(Vec3 f,Vec3 t){from=oldFrom=f;to=oldTo=t;}void update(Vec3 f,Vec3 t,int tint,boolean pulse){from=f;to=t;left=Math.max(left,4);color=tint;if(pulse)opacity=.8f;}}
 private static Vec3 point(CompoundTag p){return new Vec3(p.getDouble("x"),p.getDouble("y")+1,p.getDouble("z"));}
 private static void update(String key,Vec3 f,Vec3 t){update(key,f,t,0xffff80,true);}
 public static void update(String key,Vec3 f,Vec3 t,int color,boolean pulse){var mc=Minecraft.getInstance();if(!Double.isFinite(f.lengthSqr()+t.lengthSqr())||mc.getCameraEntity()==null)return;int limit=mc.options.graphicsMode().get()==GraphicsStatus.FAST?25:50;if(mc.getCameraEntity().position().distanceToSqr(f)>limit*limit)return;if(current!=mc.level){LINES.clear();current=mc.level;}var existing=LINES.get(key);if(existing==null)LINES.put(key,new Beam(f,t));else existing.update(f,t,color,pulse);}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent event){if(event.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(current!=mc.level){LINES.clear();current=mc.level;}if(mc.level==null||mc.player==null||mc.isPaused())return;for(var b:LINES.values()){b.oldFrom=b.from;b.oldTo=b.to;b.age++;b.left--;b.opacity=Math.max(.3f,b.opacity-.025f);}LINES.values().removeIf(b->b.left<=0);var item=mc.player.getMainHandItem();if(!item.is(Content.GUIDING_STRING.get()))return;var path=LabyrinthString.points(item);if(path.size()<=1)return;for(int i=1;i<Math.min(path.size(),LabyrinthString.MAX_POINTS);i++){var from=point(path.getCompound(i));var to=point(path.getCompound(i-1));String key=Math.floor(from.x)+","+Math.floor(from.y-1)+","+Math.floor(from.z);update(key,from,to);}if(LabyrinthString.active(item))update("player",GemEffects.hand(),point(path.getCompound(path.size()-1)));}
 // The vanilla lightmap shader discards alpha below .1, removing the entire naked-eye beam (.08).
 // Use the legacy additive shader with the ParticleEngine 1/255 cutoff for both ribbons and flares.
 @SubscribeEvent public static void render(RenderLevelStageEvent event){if(event.getStage()!=RenderLevelStageEvent.Stage.AFTER_PARTICLES||LINES.isEmpty())return;var mc=Minecraft.getInstance();if(mc.level!=current||mc.player==null)return;float partial=event.getPartialTick(),clock=mc.player.tickCount+partial,scroll=-clock*.2f-(float)Math.floor(-clock*.1f);var camera=event.getCamera().getPosition();var poses=event.getPoseStack();var buffers=mc.renderBuffers().bufferSource();var beamType=tc4revival.client.TCRenderTypes.primalSprite(BEAM);var flareType=tc4revival.client.TCRenderTypes.primalSprite(ATLAS);boolean revealing=tc4revival.content.RevealingGear.visible(mc.player,true);
  for(var line:LINES.values()){var from=line.oldFrom.lerp(line.from,partial).subtract(camera);var to=line.oldTo.lerp(line.to,partial).subtract(camera);var delta=to.subtract(from);double length=delta.length();if(length<1e-7)continue;var along=delta.scale(1/length);var first=along.cross(Math.abs(along.y)>.99?new Vec3(1,0,0):new Vec3(0,1,0)).normalize();var second=along.cross(first).normalize();var out=buffers.getBuffer(beamType);for(int i=0;i<2;i++){var width=(i==0?first:second).scale(.105);float phase=scroll-1+i/3f,alpha=line.opacity*(revealing?1:.1f);vertex(out,poses.last().pose(),to.subtract(width),1,phase+(float)length,alpha,line.color);vertex(out,poses.last().pose(),from.subtract(width),1,phase,alpha,line.color);vertex(out,poses.last().pose(),from.add(width),0,phase,alpha,line.color);vertex(out,poses.last().pose(),to.add(width),0,phase+(float)length,alpha,line.color);}
   poses.pushPose();poses.translate(to.x,to.y,to.z);poses.mulPose(event.getCamera().rotation());float size=.66f*line.opacity,u=(line.age%16)/16f,v=.3125f,alpha=line.opacity*(revealing?1:.2f);var matrix=poses.last().pose();var flare=buffers.getBuffer(flareType);vertex(flare,matrix,new Vec3(-size,-size,0),u+.0624375f,v+.0624375f,alpha,line.color);vertex(flare,matrix,new Vec3(-size,size,0),u+.0624375f,v,alpha,line.color);vertex(flare,matrix,new Vec3(size,size,0),u,v,alpha,line.color);vertex(flare,matrix,new Vec3(size,-size,0),u,v+.0624375f,alpha,line.color);poses.popPose();}
  buffers.endBatch(beamType);buffers.endBatch(flareType);
 }
 private static void vertex(VertexConsumer out,org.joml.Matrix4f m,Vec3 p,float u,float v,float alpha,int color){out.vertex(m,(float)p.x,(float)p.y,(float)p.z).color((color>>16&255)/255f,(color>>8&255)/255f,(color&255)/255f,alpha).uv(u,v).uv2(200).endVertex();}
}
